-- lmf.COUNTYNM
COMMENT ON TABLE "lmf"."COUNTYNM" IS 'This table includes FIPS number for county and state and the common name of the county.';
COMMENT ON COLUMN "lmf"."COUNTYNM"."STATE" IS 'Federal Information Processing Standard or Series (FIPS) code for the state; see STATENM table to look up FIPS codes for various states.';
COMMENT ON COLUMN "lmf"."COUNTYNM"."COUNTY" IS 'Federal Information Processing Standard or Series (FIPS); see COUNTYNM table to look up FIPS codes for various counties.';
COMMENT ON COLUMN "lmf"."COUNTYNM"."COUNTYNM" IS 'Name of the county corresponding to the FIPS codes in the county and state fields.';

-- lmf.DISTURBANCE
